INSERT INTO "homepage_pillars_items" ("_order", "_parent_id", "id", "title", "description", "image_id") VALUES (1, 2, '6a2ab4dfe3a4c5e03ab4d255', 'Observe', 'Gain complete visibility into your digital workplace. ZerofAI continuously monitors user experiences, endpoint health, application performance, and support environments to identify issues, friction points, and emerging risks before they impact productivity.
', 40);
INSERT INTO "homepage_pillars_items" ("_order", "_parent_id", "id", "title", "description", "image_id") VALUES (2, 2, '6a2ab519e3a4c5e03ab4d256', 'Predict', 'Anticipate issues before they disrupt work. ZerofAI analyzes workplace trends, user experience patterns, and system behavior to identify emerging risks, recurring problems, and performance degradation before they impact employees.
', 42);
INSERT INTO "homepage_pillars_items" ("_order", "_parent_id", "id", "title", "description", "image_id") VALUES (3, 2, '6a2ab540e3a4c5e03ab4d257', 'Automate', 'Transform insights into action. ZerofAI automatically resolves repetitive issues, orchestrates workflows, and executes predefined actions to reduce manual effort, accelerate resolution, and keep employees productive.
', 41);
