-- Data: homepage_what_is_paragraphs (3 rows)
ALTER TABLE "homepage_what_is_paragraphs" DISABLE TRIGGER ALL;
INSERT INTO "homepage_what_is_paragraphs" ("_order", "_parent_id", "id", "text") VALUES (1, 2, '6a2aaf26e3a4c5e03ab4d24d', 'Modern enterprises face growing operational complexity, fragmented support ecosystems, rising service demands, and increasing expectations for seamless digital workplace experiences.
');
INSERT INTO "homepage_what_is_paragraphs" ("_order", "_parent_id", "id", "text") VALUES (2, 2, '6a2aaf41e3a4c5e03ab4d24e', 'At its core, ZerofAI is an Enterprise Agentic AI Platform for Autonomous IT Operations that helps organizations observe, analyze, predict, and automate across their digital workplace environment. By integrating automation, workplace intelligence, service orchestration, and autonomous remediation into a unified platform, ZerofAI empowers enterprises to simplify support operations, improve employee experiences, reduce manual effort, and drive greater operational efficiency.
');
INSERT INTO "homepage_what_is_paragraphs" ("_order", "_parent_id", "id", "text") VALUES (3, 2, '6a3115ffbc024897b4bdf3e1', 'ZerofAI enables organizations to move beyond reactive support models and build a more intelligent, proactive, and autonomous workplace.
');
