-- Data: knowledge_page_faqs (10 rows)
ALTER TABLE "knowledge_page_faqs" DISABLE TRIGGER ALL;
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (1, 1, '6a2a96a4ee48501f4506fbfe', NULL, 'What is ZerofAI?', 'ZerofAI is an AI-powered autonomous IT operations platform that helps enterprises move from reactive support to proactive and predictive digital operations. It automates issue resolution, improves workplace experience, and helps IT teams operate more efficiently at scale.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (2, 1, '6a2a96e0ee48501f4506fbff', NULL, 'How is ZerofAI different from traditional IT automation?', 'Traditional automation follows predefined workflows and rules. ZerofAI goes further by continuously analyzing operational signals, identifying issues proactively, orchestrating remediation, and helping IT operations become more intelligent and autonomous.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (3, 1, '6a2a971dee48501f4506fc00', NULL, 'Is ZerofAI a platform, service, or both?', 'ZerofAI is both. Organizations can use it as a technology platform or combine it with ZerofAI-led operational services such as Autonomous Support Operations, Proactive Experience Operations, and Predictive Intelligence Operations.');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (4, 1, '6a2a993dee48501f4506fc01', NULL, 'How does Proactive Self-Healing work?', 'ZerofAI continuously detects anomalies, identifies recurring endpoint issues, and triggers automated remediation workflows to resolve disruptions before they impact users or create support tickets.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (5, 1, '6a2a997aee48501f4506fc02', NULL, 'What is Autonomous Endpoint Governance?', 'Autonomous Endpoint Governance helps organizations continuously manage endpoint compliance, security policies, provisioning, and operational health through intelligent automation and proactive control.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (6, 1, '6a2a99aeee48501f4506fc03', NULL, 'What does Sentiment Trend Analysis analyze?', 'ZerofAI analyzes workplace behavioral signals, support interactions, and digital experience patterns to identify employee frustration, dissatisfaction, and emerging experience issues early.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (7, 1, '6a2a99ceee48501f4506fc04', NULL, 'How does Predictive Health Analytics work?', 'ZerofAI analyzes historical operational patterns, real-time signals, and system behavior to identify early indicators of potential failures, helping teams act before disruptions occur.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (8, 1, '6a2a99e6ee48501f4506fc05', NULL, 'Can ZerofAI be customized to fit enterprise business needs?', 'Yes. ZerofAI is designed to adapt to enterprise environments, workflows, and operational requirements. It can be aligned with existing ITSM platforms, endpoint ecosystems, security policies, support processes, and automation use cases to match specific business needs and operational maturity.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (9, 1, '6a2a99ffee48501f4506fc06', NULL, 'What''s included in ZerofAI''s operational services?', 'ZerofAI''s services combine AI-powered automation, operational intelligence, and managed execution to help enterprises improve support operations, workplace experience, and predictive decision-making across IT environments.
');
INSERT INTO "knowledge_page_faqs" ("_order", "_parent_id", "id", "faq_id", "question", "answer") VALUES (10, 1, '6a2a9a16ee48501f4506fc07', NULL, 'Does ZerofAI replace existing IT teams?', 'No. ZerofAI is designed to augment IT teams by reducing repetitive operational workload, improving response efficiency, and helping teams focus on strategic initiatives, governance, and higher-value operational decisions. AI operations models are increasingly positioned as augmentation layers rather than direct team replacements.
');
ALTER TABLE "knowledge_page_faqs" ENABLE TRIGGER ALL;

